    LEFT OUTER JOIN {{ ref('BRONZE__TEA_STRATEGIC_BUSINESS_OPERATIONS__SAPAPI_ZCDV_T_CMTU028_EKPO') }} ekpo ON ekko.EBELN = ekpo.EBELN
    LEFT OUTER JOIN delivery ON
        try_to_number(ekpo.EBELP) = try_to_number(delivery.ITEM_NUMBER_OF_THE_REFERENCE_ITEM) AND
        ekko.EBELN = delivery.DOCUMENT_NUMBER_OF_THE_REFERENCE_DOCUMENT
),

